package java.util;
public class IdentityHashMap<K,V> extends AbstractMap<K,V> implements Map<K,V>,java.io.Serializable,Cloneable {private final ArrayList<K> keys=new ArrayList<K>();private final ArrayList<V> vals=new ArrayList<V>();public IdentityHashMap(){}public IdentityHashMap(int expectedMaxSize){if(expectedMaxSize<0)throw new IllegalArgumentException();}public IdentityHashMap(Map<? extends K,? extends V> m){putAll(m);}private int index(Object k){for(int i=0;i<keys.size();i++)if(keys.get(i)==k)return i;return -1;}public int size(){return keys.size();}public boolean containsKey(Object k){return index(k)>=0;}public boolean containsValue(Object v){for(V x:vals)if(x==v)return true;return false;}public V get(Object k){int i=index(k);return i<0?null:vals.get(i);}public V put(K k,V v){int i=index(k);if(i>=0)return vals.set(i,v);keys.add(k);vals.add(v);return null;}public V remove(Object k){int i=index(k);if(i<0)return null;keys.remove(i);return vals.remove(i);}public void clear(){keys.clear();vals.clear();}public Set<Entry<K,V>> entrySet(){return new AbstractSet<Entry<K,V>>(){public int size(){return keys.size();}public Iterator<Entry<K,V>> iterator(){return new Iterator<Entry<K,V>>(){int i,last=-1;public boolean hasNext(){return i<keys.size();}public Entry<K,V> next(){if(!hasNext())throw new NoSuchElementException();final K k=keys.get(i);last=i++;return new Entry<K,V>(){public K getKey(){return k;}public V getValue(){return IdentityHashMap.this.get(k);}public V setValue(V v){return IdentityHashMap.this.put(k,v);}public boolean equals(Object o){if(!(o instanceof Entry))return false;Entry e=(Entry)o;return k==e.getKey()&&getValue()==e.getValue();}public int hashCode(){return System.identityHashCode(k)^System.identityHashCode(getValue());}public String toString(){return k+"="+getValue();}};}public void remove(){if(last<0)throw new IllegalStateException();keys.remove(last);vals.remove(last);i=last;last=-1;}};}};}public Object clone(){return new IdentityHashMap<K,V>(this);}}
